// Recibe { documento, contenido } y devuelve un item por seccion de nivel 2 (`## `).
// La seccion viaja como metadato para que la recuperacion sepa de donde salio cada
// fragmento, y para poder filtrar por ella mas adelante.
//
// Se lee del Webhook y no de $input porque el nodo anterior (la limpieza en Postgres)
// corre con executeOnce y reemplaza los items por su propio resultado.

const body = $('Webhook Ingesta').first().json.body ?? {};
const documento = String(body.documento || '').trim();
const contenido = String(body.contenido || '');

if (!documento) throw new Error('Falta `documento`: el nombre con el que se identifica el corpus.');
if (contenido.trim().length === 0) throw new Error('Falta `contenido`: el texto del documento.');

// Se corta en los encabezados de nivel 2 conservando el titulo de cada seccion.
const partes = contenido.split(/^##\s+/m);

// Lo que va antes del primer `## ` es la cabecera del documento; se conserva
// como una seccion propia para no perder el contexto de que es este documento.
const secciones = [];
const cabecera = partes.shift();
if (cabecera && cabecera.trim().length > 0) {
  secciones.push({ seccion: 'Introduccion', texto: cabecera.trim() });
}
for (const parte of partes) {
  const salto = parte.indexOf('\n');
  const titulo = (salto === -1 ? parte : parte.slice(0, salto)).trim();
  const cuerpo = (salto === -1 ? '' : parte.slice(salto + 1)).trim();
  if (cuerpo.length === 0) continue;
  // El titulo se repite dentro del texto: cada fragmento debe poder responder
  // por si solo de que habla, aunque el troceado lo separe del encabezado.
  secciones.push({ seccion: titulo, texto: titulo + '\n\n' + cuerpo });
}

if (secciones.length === 0) throw new Error('El documento no produjo ninguna seccion.');

return secciones.map((s) => ({ json: { documento, seccion: s.seccion, texto: s.texto } }));

// Deja constancia de cuanto se indexo, que es un criterio del ticket.
const fragmentos = $input.all();
const porSeccion = {};
for (const f of fragmentos) {
  const s = f.json?.metadata?.seccion ?? '(sin seccion)';
  porSeccion[s] = (porSeccion[s] ?? 0) + 1;
}
return [{ json: {
  ok: true,
  documento: $('Partir por seccion').first().json.documento,
  secciones: Object.keys(porSeccion).length,
  fragmentos: fragmentos.length,
  troceado: { chunkSize: 1000, chunkOverlap: 150 },
  modelo_embeddings: 'text-embedding-3-small',
  dimensiones: 1536,
  por_seccion: porSeccion,
} }];
